import React from 'react';

const SuccessMessage = ({ formData }) => {
  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100 p-6">
      <div className="bg-white rounded-lg shadow-xl p-8 max-w-lg w-full">
        <h2 className="text-3xl font-semibold text-green-600 mb-4 text-center">Quiz Created Successfully!</h2>
        <h4 className="text-xl font-medium mb-4 text-gray-700">Quiz Details:</h4>

        <div className="space-y-2 text-lg text-gray-600">
          <p><strong>Name:</strong> <span className="text-green-500">{formData.name}</span></p>
          <p><strong>Exam:</strong> {formData.exam}</p>
          <p><strong>Difficulty Levels:</strong> {formData.difficultyLevels.join(', ')}</p>
          <p><strong>Class / Year:</strong> {formData.classYear}</p>
          <p><strong>Subjects:</strong> {formData.subjects.join(', ')}</p>
          <p><strong>Topics:</strong> {formData.topics.join(', ')}</p>
          <p><strong>Quiz Mode:</strong> {formData.quizMode}</p>
          <p><strong>Number of Questions:</strong> {formData.numberOfQuestions}</p>

          {formData.addHints && <p><strong>Hints:</strong> Enabled</p>}
          {formData.answerExplanation && <p><strong>Answer Explanation:</strong> Enabled</p>}
          {formData.breakIntoSubtopics && <p><strong>Break Into Subtopics:</strong> Enabled</p>}
        </div>

        <div className="mt-6 flex justify-center">
          <button
            className="bg-green-500 text-white py-2 px-6 rounded-lg shadow-lg hover:bg-green-600 focus:outline-none focus:ring-2 focus:ring-green-500"
            onClick={() => window.location.reload()} // Optionally reload or reset the form
          >
            Create Another Quiz
          </button>
        </div>
      </div>
    </div>
  );
}

export default SuccessMessage;
